/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');
const dir = '/workspace/requirements';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.yaml')).sort();
for (const f of files) {
  const full = path.join(dir, f);
  const data = yaml.load(fs.readFileSync(full, 'utf8'));
  const slug = path.basename(f, '.yaml');
  const title = (data.title || '').replace(/\\s+/g, ' ').trim();
  const req = (data.requirement || '').replace(/\\s+/g, ' ').trim();
  console.log('--- ' + slug + ' ---');
  console.log(title);
  console.log(req);
}
NODE"

