/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const path = require('path');
const https = require('https');
const mapping = JSON.parse(fs.readFileSync('/workspace/requirements/.rename_map.json', 'utf8'));
const entries = Object.entries(mapping)
  .map(([oldName, newName]) => ({pr: Number(oldName.replace(/\\.yaml"'$/, '"'')), slug: newName.replace(/\\.yaml"'$/, '"'')}))
  .sort((a, b) => a.pr - b.pr);
function getJson(url) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, {
      headers: {
        'User-Agent': 'codex-agent',
        'Accept': 'application/vnd.github+json'
      }
    }, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        if (res.statusCode < 200 || res.statusCode >= 300) {
          reject(new Error('HTTP ' + res.statusCode + ' for ' + url + '\\n' + data));
          return;
        }
        resolve(JSON.parse(data));
      });
    });
    req.on('error', reject);
  });
}
(async () => {
  const out = [];
  for (const entry of entries) {
    const pr = await getJson("'`https://api.github.com/repos/apache/echarts/pulls/${entry.pr}`);
    out.push({
      ...entry,
      title: pr.title,
      state: pr.state,
      merged: !!pr.merged_at,
      base: pr.base && pr.base.ref,
      merge_commit_sha: pr.merge_commit_sha,
      head_sha: pr.head && pr.head.sha,
      head_ref: pr.head && pr.head.ref
    });
  }
  fs.writeFileSync('"'/tmp/echarts-pr-meta.json', JSON.stringify(out, null, 2));
  for (const item of out) {
    console.log([item.pr, item.slug, item.base, item.merge_commit_sha, item.head_sha, item.title].join('\\t'));
  }
})();
NODE"

